// TranscriptGroup is one reassembled call transcript for the History
// tab: the call's remote party plus its segments in spoken order.
type TranscriptGroup struct {
	// CallID addresses the call for the delete affordance (the store's
	// DeleteCall key — the CDR rows carry no call uuid, so this is the
	// ONLY correlation handle the transcript section has).
	CallID    string
	Remote    string
	Direction string // "in" | "out"
	StartedAt time.Time
	Lines     []string
	// Note is the owner's saved post-call note (optional; empty renders
	// an empty editor box).
	Note string
	// Disposition is the operator-confirmed verdict on the note slot
	// (T3; empty = never confirmed — renders no badge).
	Disposition string
	// ReviewState is the automatic post-call review's lifecycle state
	// (issue #8, T13): pending/present/failed; empty = no review was
	// ever asked for this call. ReviewText/ReviewConfidence carry the
	// present state's draft dims.
	ReviewState      string
	ReviewText       string
	ReviewConfidence int
}

